block='''-- P0.29.71 exact source reconstruction: captured P0.29 R0 state plus P2/P12.\nfunction M.set_native_aim_assist(enabled)\n    local saved = native_aim_state_029.custom_dongdong_native_aim_state\n    if type(saved) ~= "table" then\n        saved = {}\n        native_aim_state_029.custom_dongdong_native_aim_state = saved\n    end\n    local import_fn = rawget(_G, "import")\n    local get_world = rawget(_G, "GetWorld")\n    if type(import_fn) ~= "function" or type(get_world) ~= "function" then return false end\n    local ok_class, cls = pcall(import_fn, "ClientBaseSetting")\n    local ok_world, world = pcall(get_world)\n    if not ok_class or not ok_world or cls == nil or world == nil then return false end\n    local getter = safe_get_029_2(cls, "Get")\n    local ok_get, object = call_optional_self_029_12(getter, cls, world)\n    if not ok_get or object == nil then return false end\n    if saved.saved ~= true then\n        saved.saved = true\n        saved.value = safe_get_029_2(object, "bIsAimAssistOpen") == true\n    end\n    local desired = enabled == true and true or (saved.value == true)\n    local function set_value() object.bIsAimAssistOpen = desired end\n    local set_ok = pcall(set_value)\n    local saver = safe_get_029_2(object, "SaveDataConfig")\n    if type(saver) == "function" then pcall(saver, object) end\n    if enabled ~= true then saved.saved = false end\n    return set_ok\nend\n\n'''
