aim_runtime_map["prototypes"]["0.29.71.0"]={"prototype_id":"0.29.71.0","numparams":p710["numparams"],"instruction_count":p710["instruction_count"],"upvalues":p710["upvalues"],"child_count":p710["child_count"],"parent_prototype":"0.29.71","parent_capture_mapping":[{"upvalue":"U0","from":"P0.29.71 local R10 target object","descriptor":p710["upvalues"][0]},{"upvalue":"U1","from":"P0.29.71 local R11 desired boolean","descriptor":p710["upvalues"][1]}],"source_symbol":"AimRuntime.set_native_aim_assist nested setter","source_file":"src/spectra/aim_runtime.lua","return_contract":"exactly zero values on normal completion","branch_order":"assign captured desired boolean to captured target bIsAimAssistOpen","source_capture_identity":"fresh child per parent call capturing target and desired","source_only_dependency":True,"current_ownership":"source_owned","payload_closure_rebinding":False}
